<style>
:root{--ink:#173f38;--paper:#f4efd9;--cream:#fffaf0;--blue:#175b91;--orange:#ef6d2f;--yellow:#f6c24f;--line:rgba(23,63,56,.2);--shadow:0 18px 50px rgba(16,46,40,.18)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);background:var(--paper);font-family:"Avenir Next","Gill Sans",Candara,sans-serif;min-height:100vh;overflow-x:hidden}button,a{font:inherit}button{cursor:pointer;color:inherit}.grain{position:fixed;inset:0;pointer-events:none;opacity:.16;z-index:20;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.22'/%3E%3C/svg%3E")}
.mast{position:relative;min-height:66vh;padding:22px clamp(18px,4vw,58px) 46px;display:grid;grid-template-rows:auto 1fr;overflow:hidden;background:var(--ink);color:var(--cream)}.mast:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(15,49,43,.96),rgba(15,49,43,.7) 50%,rgba(15,49,43,.12)),url('assets/twin-atlas-map.webp') center/cover no-repeat;filter:saturate(.9);transform:scale(1.02);z-index:0}.mast>*{position:relative;z-index:1}.topbar{display:flex;justify-content:space-between;align-items:center;gap:18px;border-bottom:1px solid rgba(255,250,240,.28);padding-bottom:16px}.back{color:inherit;text-decoration:none;font-weight:750;letter-spacing:.06em;text-transform:uppercase;font-size:.74rem}.back:hover{text-decoration:underline}.edition{font-family:"Courier New",monospace;font-size:.72rem;opacity:.72}.hero{align-self:end;max-width:730px;padding-top:70px}.kicker{display:flex;align-items:center;gap:10px;text-transform:uppercase;font-weight:800;letter-spacing:.16em;font-size:.74rem;color:var(--yellow)}.kicker:before{content:"";width:42px;border-top:2px solid currentColor}.hero h1{font-family:Baskerville,"Iowan Old Style","Palatino Linotype",serif;font-size:clamp(3.3rem,9vw,7.8rem);font-weight:600;line-height:.78;letter-spacing:-.055em;margin:22px 0 24px}.hero h1 em{display:block;color:var(--yellow);font-style:italic;margin-left:clamp(20px,9vw,135px)}.hero p{max-width:590px;font-size:clamp(1rem,2vw,1.25rem);line-height:1.6;margin:0;color:#e6eadf}.scroll-cue{display:inline-flex;gap:10px;align-items:center;margin-top:28px;color:var(--cream);text-decoration:none;font-size:.78rem;font-weight:800;text-transform:uppercase;letter-spacing:.12em}.scroll-cue span{width:28px;height:28px;border:1px solid rgba(255,255,255,.6);border-radius:50%;display:grid;place-items:center;animation:bob 1.8s ease-in-out infinite}@keyframes bob{50%{transform:translateY(5px)}}
main{width:min(1280px,100%);margin:auto;padding:clamp(34px,6vw,78px) clamp(14px,3vw,40px) 80px}.brief{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(250px,.8fr);gap:34px;align-items:end;margin-bottom:28px}.brief h2{font-family:Baskerville,"Iowan Old Style",serif;font-size:clamp(2.2rem,5vw,4.7rem);line-height:.95;letter-spacing:-.045em;margin:0}.brief p{line-height:1.62;margin:0;color:#3d5e55;max-width:540px}.rule{display:inline-block;background:var(--orange);color:white;border-radius:999px;padding:6px 12px;font-size:.72rem;letter-spacing:.1em;text-transform:uppercase;font-weight:900;margin-bottom:12px}
.desk{background:#d8d1b5;border:1px solid rgba(23,63,56,.2);box-shadow:var(--shadow);padding:clamp(9px,1.8vw,20px);position:relative}.desk:before{content:"FIELD UNIT 05-11";position:absolute;right:13px;top:-27px;font-family:"Courier New",monospace;font-weight:bold;font-size:.72rem;letter-spacing:.13em;transform:rotate(1deg);border:2px solid var(--orange);color:var(--orange);padding:4px 8px}.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:10px}.tool{border:1px solid rgba(23,63,56,.28);background:var(--cream);border-radius:2px;min-height:42px;padding:9px 13px;font-weight:850;box-shadow:0 2px 0 rgba(23,63,56,.16)}.tool:hover,.tool:focus-visible{background:#fff;transform:translateY(-1px)}.tool.active{background:var(--ink);color:white}.zoom-readout{font-family:"Courier New",monospace;font-size:.78rem;margin-left:auto;font-weight:bold}.maps{display:grid;grid-template-columns:1fr 1fr;gap:10px}.map-shell{min-width:0;background:var(--cream);border:2px solid var(--ink)}.map-head{height:44px;padding:0 12px;display:flex;align-items:center;justify-content:space-between;background:var(--ink);color:var(--cream);font-size:.78rem;letter-spacing:.09em;text-transform:uppercase;font-weight:900}.lamp{display:inline-block;width:8px;height:8px;border-radius:50%;background:#6da69a;margin-right:6px;box-shadow:0 0 0 2px rgba(255,255,255,.15)}.map-head b{color:var(--yellow)}.viewport{position:relative;aspect-ratio:1.2/1;overflow:hidden;touch-action:none;cursor:grab;background:#bfd4c8}.viewport.dragging{cursor:grabbing}.map-image{position:absolute;width:145%;height:145%;left:-22.5%;top:-22.5%;object-fit:cover;max-width:none;user-select:none;pointer-events:none;transform-origin:center;will-change:transform}.engine-b .map-image{filter:saturate(.74) contrast(1.14) sepia(.12)}.engine-a .map-image{filter:saturate(1.12) contrast(.98)}.gridlines{position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(rgba(255,255,255,.17) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.17) 1px,transparent 1px);background-size:40px 40px;mix-blend-mode:overlay}.pin{position:absolute;width:30px;height:30px;border:0;background:transparent;transform:translate(-50%,-50%);padding:0;z-index:4}.pin:before{content:"";position:absolute;inset:6px;border-radius:50% 50% 50% 0;background:var(--orange);transform:rotate(-45deg);box-shadow:0 2px 0 #7f3518,0 0 0 3px white}.pin:after{content:"";position:absolute;width:5px;height:5px;border-radius:50%;background:white;left:12.5px;top:12px}.pin:hover{transform:translate(-50%,-50%) scale(1.15)}.pin.found:before{background:var(--yellow);box-shadow:0 2px 0 #8b6b1b,0 0 0 3px white}.pin.found{animation:pop .45s ease}@keyframes pop{50%{transform:translate(-50%,-50%) scale(1.55)}}.pin[data-id="0"]{left:18%;top:32%}.pin[data-id="1"]{left:78%;top:24%}.pin[data-id="2"]{left:52%;top:60%}.pin[data-id="3"]{left:31%;top:76%}.pin[data-id="4"]{left:84%;top:72%}.pin[data-id="5"]{left:62%;top:36%}.unfound .pin{opacity:0}.unfound .pin:hover,.unfound .pin:focus-visible{opacity:.22}.map-foot{display:flex;justify-content:space-between;padding:7px 10px;background:#ede7d3;color:#506960;font-family:"Courier New",monospace;font-size:.65rem}.sync-line{height:36px;display:flex;align-items:center;justify-content:center;gap:10px;color:#415e55;font-size:.72rem;text-transform:uppercase;letter-spacing:.13em;font-weight:850}.sync-line:before,.sync-line:after{content:"";height:1px;background:rgba(23,63,56,.24);flex:1}.sync-pulse{width:9px;height:9px;border-radius:50%;background:var(--orange);box-shadow:0 0 0 5px rgba(239,109,47,.2);animation:pulse 1.8s infinite}@keyframes pulse{50%{box-shadow:0 0 0 10px rgba(239,109,47,0)}}
.caseboard{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}.missions{background:var(--cream);border:1px solid var(--line);padding:18px}.missions h3,.report h3{font-family:Baskerville,"Iowan Old Style",serif;font-size:1.7rem;margin:0 0 13px}.clues{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.clue{border:1px solid var(--line);background:transparent;padding:12px;text-align:left;min-height:72px;display:flex;gap:11px;align-items:flex-start}.clue-num{border:1px solid var(--ink);border-radius:50%;width:26px;height:26px;flex:none;display:grid;place-items:center;font:700 .75rem "Courier New",monospace}.clue strong{display:block;font-size:.86rem;margin-bottom:3px}.clue small{color:#6a7d76;line-height:1.35}.clue.done{background:#e7eedb;border-color:#8fa071}.clue.done .clue-num{background:var(--ink);color:white}.report{background:var(--blue);color:white;padding:20px;display:flex;flex-direction:column}.score{font:700 clamp(3rem,7vw,5rem) Baskerville,serif;color:var(--yellow);line-height:1}.score span{font-size:1rem;color:white;font-family:"Avenir Next",sans-serif}.report p{line-height:1.5;color:#dce7ea;min-height:52px}.stamp{margin-top:auto;border:2px solid rgba(255,255,255,.65);background:transparent;color:white;text-transform:uppercase;letter-spacing:.1em;padding:11px;font-weight:900;transform:rotate(-1deg)}.stamp:disabled{opacity:.35;cursor:not-allowed}.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,140%);background:var(--ink);color:white;padding:12px 18px;z-index:30;box-shadow:var(--shadow);font-weight:800;transition:.3s;max-width:calc(100% - 28px);text-align:center}.toast.show{transform:translate(-50%,0)}
.epilogue{margin:80px auto 0;max-width:880px;display:grid;grid-template-columns:110px 1fr;gap:24px;border-top:1px solid var(--line);padding-top:28px}.year{font:600 3rem Baskerville,serif;color:var(--orange)}.epilogue h2{font:600 clamp(1.8rem,4vw,3rem) Baskerville,serif;margin:0 0 10px}.epilogue p{line-height:1.7;color:#466158;margin:0}.epilogue a{color:var(--blue);font-weight:850}.tiny{margin-top:50px;text-align:center;font-size:.75rem;color:#72837d}.tiny a{color:inherit}
@media(max-width:760px){.mast{min-height:600px}.mast:after{background-position:58% center}.hero{padding-top:56px}.brief{grid-template-columns:1fr}.maps{grid-template-columns:1fr}.caseboard{grid-template-columns:1fr}.clues{grid-template-columns:1fr}.sync-line{display:none}.map-shell:first-child{margin-bottom:2px}.epilogue{grid-template-columns:1fr}.year{font-size:2rem}.map-head{height:40px}.viewport{aspect-ratio:1.32/1}.zoom-readout{width:100%;margin:3px 0 0}.toolbar{align-items:stretch}.tool{flex:1}.tool[data-action="reset"]{flex-basis:100%}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
