<body>
<div class="grain"></div>
<header class="mast"><nav class="topbar"><a class="back" href="index.php">← Chloe Reads Jon</a><span class="edition">FIELD EDITION / 2005</span></nav><div class="hero"><div class="kicker">Two engines. One town.</div><h1>Twin Atlas <em>Detective</em></h1><p>Pan one map and its twin follows. Compare their cartographic personalities, locate six mismatched signals, and decide whether linked views make a sharper pair of eyes.</p><a class="scroll-cue" href="#case">Open the case <span>↓</span></a></div></header>
<main id="case">
<section class="brief"><div><span class="rule">Case 0511</span><h2>The same place is never quite the same map.</h2></div><p>Drag either atlas to pan both. Zoom, unlink them if you dare, then tap the hidden discrepancies. On a phone the maps stack, but their viewports remain synchronized.</p></section>
<section class="desk" aria-label="Linked map comparison game">
<div class="toolbar"><button class="tool" data-action="minus" aria-label="Zoom out">−</button><button class="tool" data-action="plus" aria-label="Zoom in">+</button><button class="tool active" data-action="sync" aria-pressed="true">◎ Linked</button><button class="tool" data-action="reveal">Hint</button><button class="tool" data-action="reset">Reset case</button><span class="zoom-readout">ZOOM 100% · 6 SIGNALS</span></div>
<div class="maps">
<article class="map-shell engine-a"><div class="map-head"><span><i class="lamp"></i>Atlas <b>Cedar</b></span><span>Raster / AJAX</span></div><div class="viewport"><img class="map-image" src="assets/twin-atlas-map.webp" alt="An illustrated map of a coastal Pacific Northwest town"><div class="gridlines"></div><button class="pin" data-id="0" aria-label="Investigate ferry discrepancy"></button><button class="pin" data-id="1" aria-label="Investigate lighthouse discrepancy"></button><button class="pin" data-id="2" aria-label="Investigate bridge discrepancy"></button><button class="pin" data-id="3" aria-label="Investigate forest discrepancy"></button><button class="pin" data-id="4" aria-label="Investigate road discrepancy"></button><button class="pin" data-id="5" aria-label="Investigate inlet discrepancy"></button></div><div class="map-foot"><span>CEDAR RENDERER 2.4</span><span>47 tiles</span></div></article>
<article class="map-shell engine-b"><div class="map-head"><span><i class="lamp"></i>Atlas <b>Signal</b></span><span>Vector / FLASH</span></div><div class="viewport"><img class="map-image" src="assets/twin-atlas-map.webp" alt="The same coastal map in a contrasting cartographic style"><div class="gridlines"></div><button class="pin" data-id="0" aria-label="Investigate ferry discrepancy"></button><button class="pin" data-id="1" aria-label="Investigate lighthouse discrepancy"></button><button class="pin" data-id="2" aria-label="Investigate bridge discrepancy"></button><button class="pin" data-id="3" aria-label="Investigate forest discrepancy"></button><button class="pin" data-id="4" aria-label="Investigate road discrepancy"></button><button class="pin" data-id="5" aria-label="Investigate inlet discrepancy"></button></div><div class="map-foot"><span>SIGNAL RENDERER 5.1</span><span>43 tiles</span></div></article>
</div>
<div class="sync-line"><span>viewport relay</span><i class="sync-pulse"></i><span id="syncStatus">coordinates locked</span></div>
<div class="caseboard"><div class="missions"><h3>Discrepancy docket</h3><div class="clues" id="clues"></div></div><aside class="report"><h3>Case progress</h3><div class="score"><b id="foundCount">0</b><span> / 6 found</span></div><p id="verdict">The twins look innocent. Start dragging, zooming, and checking suspicious landmarks.</p><button class="stamp" id="closeCase" disabled>Close the case</button></aside></div>
</section>
<section class="epilogue"><div class="year">2005</div><div><h2>Before “compare mode” was a button</h2><p>Jon wired Google Maps and three Yahoo! Maps renderers together so panning and zooming one moved all the others. This little field desk keeps the delightful core of that experiment: comparison becomes useful when every viewport tells the same geographic story at once. <a href="<?= htmlspecialchars($sourceUrl, ENT_QUOTES) ?>">Inspired by Jon’s “Google Maps and Yahoo Maps, side-by-side.”</a></p></div></section>
<div class="tiny"><a href="index.php">Back to the Chloe Reads Jon collection</a></div>
</main>
<div class="toast" role="status" aria-live="polite"></div>
<script>
const clues=[['Ferry wake','One renderer sees a wake twice as long.'],['Lighthouse pulse','A beam lands a few degrees north.'],['Suspension bridge','The centre span has gained a suspicious lane.'],['Cedar boundary','Three trees have wandered across the contour.'],['Cliff road','One hairpin bend is missing entirely.'],['Hidden inlet','The shoreline disagrees about a tiny cove.']];
const state={x:0,y:0,z:1,linked:true,found:new Set(),hint:false};
const viewports=[...document.querySelectorAll('.viewport')],images=[...document.querySelectorAll('.map-image')],clueBox=document.querySelector('#clues'),toast=document.querySelector('.toast'),readout=document.querySelector('.zoom-readout');
clueBox.innerHTML=clues.map((c,i)=>`<button class="clue" data-id="${i}"><span class="clue-num">${i+1}</span><span><strong>${c[0]}</strong><small>${c[1]}</small></span></button>`).join('');
function render(source){images.forEach((img,i)=>{if(state.linked||!source||viewports[i]===source)img.style.transform=`translate(${state.x}px,${state.y}px) scale(${state.z})`});readout.textContent=`ZOOM ${Math.round(state.z*100)}% · ${6-state.found.size} SIGNAL${state.found.size===5?'':'S'}`;document.querySelector('#syncStatus').textContent=state.linked?'coordinates locked':'independent view'}
function flash(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(flash.t);flash.t=setTimeout(()=>toast.classList.remove('show'),2100)}
function mark(id){id=Number(id);if(state.found.has(id)){flash('Already filed: '+clues[id][0]);return}state.found.add(id);document.querySelectorAll(`.pin[data-id="${id}"],.clue[data-id="${id}"]`).forEach(el=>el.classList.add('found','done'));document.querySelector('#foundCount').textContent=state.found.size;const words=['One signal filed. The mapmakers are getting nervous.','Two down. A pattern is taking shape.','Halfway. The town is beginning to confess.','Four filed. Excellent cartographic nosiness.','One discrepancy remains in the wild.','Case complete. Two maps, one very sharp detective.'];document.querySelector('#verdict').textContent=words[state.found.size-1];if(state.found.size===6)document.querySelector('#closeCase').disabled=false;flash(clues[id][0]+' filed ✓')}
document.addEventListener('click',e=>{const pin=e.target.closest('.pin');if(pin)mark(pin.dataset.id);const clue=e.target.closest('.clue');if(clue)mark(clue.dataset.id);const btn=e.target.closest('[data-action]'),act=btn?.dataset.action;if(!act)return;if(act==='plus')state.z=Math.min(2.2,state.z+.2);if(act==='minus')state.z=Math.max(.8,state.z-.2);if(act==='sync'){state.linked=!state.linked;btn.classList.toggle('active',state.linked);btn.setAttribute('aria-pressed',String(state.linked));btn.textContent=state.linked?'◎ Linked':'○ Unlinked';flash(state.linked?'Viewports locked together':'Maps unlinked — cartographic chaos enabled')}if(act==='reveal'){state.hint=!state.hint;document.querySelector('.maps').classList.toggle('unfound',!state.hint);btn.textContent=state.hint?'Hide pins':'Hint';flash(state.hint?'Signal pins exposed for ten seconds':'Hints tucked away');if(state.hint)setTimeout(()=>{state.hint=false;document.querySelector('.maps').classList.add('unfound');btn.textContent='Hint'},10000)}if(act==='reset'){state.x=state.y=0;state.z=1;state.found.clear();document.querySelectorAll('.found,.done').forEach(el=>el.classList.remove('found','done'));document.querySelector('#foundCount').textContent='0';document.querySelector('#verdict').textContent='The twins look innocent. Start dragging, zooming, and checking suspicious landmarks.';document.querySelector('#closeCase').disabled=true;flash('Fresh case sheet loaded')}render()});
let drag=null;viewports.forEach(v=>{v.addEventListener('pointerdown',e=>{if(e.target.closest('.pin'))return;drag={v,x:e.clientX,y:e.clientY,sx:state.x,sy:state.y};v.setPointerCapture(e.pointerId);v.classList.add('dragging')});v.addEventListener('pointermove',e=>{if(!drag||drag.v!==v)return;state.x=Math.max(-130,Math.min(130,drag.sx+e.clientX-drag.x));state.y=Math.max(-100,Math.min(100,drag.sy+e.clientY-drag.y));render(v)});v.addEventListener('pointerup',()=>{v.classList.remove('dragging');drag=null});v.addEventListener('wheel',e=>{e.preventDefault();state.z=Math.max(.8,Math.min(2.2,state.z+(e.deltaY<0?.1:-.1)));render(v)},{passive:false})});
document.querySelector('.maps').classList.add('unfound');document.querySelector('#closeCase').addEventListener('click',()=>{flash('CASE 0511 CLOSED · Cartographic intuition: excellent');document.querySelector('.report').style.background='#173f38'});render();
</script>
